<script setup lang="ts">
import {computed,ref} from 'vue';import {helpEntries} from '../state/help';import Icon from './Icon.vue';import {t} from '../state/appearance';
const props=defineProps<{label:string;text?:string;helpKey?:string;items?:{term:string;description:string;origin?:string;layer?:string}[]}>();const entries=computed(()=>props.items??helpEntries(props.helpKey??''));const dialog=ref<HTMLDialogElement>();
</script>
<template><button class="icon-button help-button" :aria-label="t('Подробности: ','Details: ')+label" :data-tooltip="t('Подробности: ','Details: ')+label" @click="dialog?.showModal()"><Icon name="help-circle"/></button><dialog ref="dialog" class="help-dialog" :class="{'has-layers':entries.some(entry=>entry.origin)}" :aria-label="label" @click="($event.target===dialog)&&dialog?.close()"><header><strong>{{label}}</strong><button class="icon-button" :aria-label="t('Закрыть','Close')" @click="dialog?.close()"><Icon name="x"/></button></header><div class="dialog-body"><div v-if="entries.some(entry=>entry.origin)" class="table-wrap help-layers"><table><thead><tr><th>{{t('Понятие','Term')}}</th><th>{{t('Происхождение','Origin')}}</th><th>{{t('Логический слой','Logical layer')}}</th><th>{{t('Объяснение','Explanation')}}</th></tr></thead><tbody><tr v-for="entry in entries" :key="entry.term"><th scope="row">{{entry.term}}</th><td>{{entry.origin}}</td><td>{{entry.layer}}</td><td>{{entry.description}}</td></tr></tbody></table></div><dl v-else-if="entries.length" class="help-glossary"><div v-for="entry in entries" :key="entry.term"><dt>{{entry.term}}</dt><dd>{{entry.description}}</dd></div></dl><p v-else>{{text}}</p></div><form method="dialog"><button>{{t('Закрыть','Close')}}</button></form></dialog></template>
